//! **The notices beside the executables name what the executables are built from**, held by a
//! test rather than remembered.
//!
//! A release puts `argmind-app.exe` and `argmind.exe` in somebody's hands, and an executable carries
//! none of the licence files its crates came with. MIT asks for its copyright notice in every copy,
//! and most of this graph is MIT. So `THIRD-PARTY-NOTICES.txt` is generated by
//! `examples/notices.rs`, and this fails when it and the graph disagree **in either direction**:
//! a crate that moved a patch version is missing from it, and a crate that left is still named. The
//! second half is the one `licences.rs` taught: a record that keeps listing what was removed reads
//! as thorough while being wrong.
//!
//! **It runs `cargo tree`**, offline and locked, through the same `argmind_rules::linked` the
//! generator uses, so the two cannot be reading different graphs. That is a subprocess in a test,
//! which nothing else here does; the alternative was reading `Cargo.lock`, which holds every
//! platform's and every dev-dependency's crates and so would demand notices for code that ships in
//! nothing.
//!
//! **What it does not check**: that a section's text is the right text. It checks that each crate
//! has a section with at least one file in it, and that the WebView2 loader's licence was read for
//! the loader this graph links. Regenerate with
//! `cargo run --manifest-path native/Cargo.toml -p argmind-rules --example notices`.

use argmind_rules::{linked, root, Linked, WEBVIEW2_SDK, WEBVIEW2_SYS};
use std::collections::BTreeSet;
use std::sync::OnceLock;

const REGENERATE: &str =
    "regenerate it: cargo run --manifest-path native/Cargo.toml -p argmind-rules --example notices";

fn graph() -> &'static [Linked] {
    static GRAPH: OnceLock<Vec<Linked>> = OnceLock::new();
    GRAPH.get_or_init(|| linked().unwrap_or_else(|e| panic!("the release graph could not be read: {e}")))
}

fn notices() -> String {
    let path = root().join("THIRD-PARTY-NOTICES.txt");
    std::fs::read_to_string(&path).unwrap_or_else(|_| panic!("{} is missing; {REGENERATE}", path.display()))
        .replace("\r\n", "\n")
}

/// `name version` of every section, off its `crate:` line.
fn listed(text: &str) -> BTreeSet<String> {
    text.lines().filter_map(|l| l.strip_prefix("crate: ")).map(str::to_string).collect()
}

fn key(c: &Linked) -> String {
    format!("{} {}", c.name, c.version)
}

#[test]
fn every_crate_in_the_executables_has_its_notice() {
    let listed = listed(&notices());
    let missing: Vec<String> = graph().iter().map(key).filter(|k| !listed.contains(k)).collect();
    assert!(missing.is_empty(), "built into the executables and not in THIRD-PARTY-NOTICES.txt: \
                                 {missing:?}; {REGENERATE}");
}

#[test]
fn the_notices_name_nothing_the_executables_no_longer_contain() {
    let built: BTreeSet<String> = graph().iter().map(key).collect();
    let stale: Vec<String> = listed(&notices()).into_iter().filter(|k| !built.contains(k)).collect();
    assert!(stale.is_empty(), "named in THIRD-PARTY-NOTICES.txt and no longer built in: {stale:?}; \
                               {REGENERATE}");
}

#[test]
fn every_section_carries_a_licence_text() {
    let text = notices();
    let mut empty = Vec::new();
    for section in text.split("\ncrate: ").skip(1) {
        let name = section.lines().next().unwrap_or_default().to_string();
        if !section.lines().any(|l| l.starts_with("--- ") && l.ends_with(" ---")) {
            empty.push(name);
        }
    }
    assert!(empty.is_empty(), "sections with no licence file in them: {empty:?}");
}

/// **The loader's licence belongs to one loader.** `webview2-com-sys` carries Microsoft's prebuilt
/// `WebView2LoaderStatic.lib` and ships no licence for it, so the SDK's licence was read for the
/// version that loader reports. A new `webview2-com-sys` may carry a new loader.
#[test]
fn the_webview2_loader_licence_was_read_for_the_loader_that_is_linked() {
    let sys = graph().iter().find(|c| c.name == "webview2-com-sys")
        .expect("webview2-com-sys has left the graph: the loader notice and this test can go too");
    assert_eq!(sys.version, WEBVIEW2_SYS,
               "webview2-com-sys moved: read the WebView2 SDK licence of the loader it now carries \
                (its x64/WebView2Loader.dll version resource names the SDK), replace \
                native/argmind-rules/notices/webview2-sdk-*.txt, and update WEBVIEW2_SYS and WEBVIEW2_SDK");
    let text = notices();
    assert!(text.contains(&format!("WebView2 SDK {WEBVIEW2_SDK}")), "the loader's SDK is not named");
    assert!(text.contains("Copyright (C) Microsoft Corporation. All rights reserved."),
            "the SDK's licence text is not in the notices");
}
